function DogName({ time }) {
  const [dog, setDog] = useState('');        // only this component reads it
  return (
    <>
      <input value={dog} onChange={(e) => setDog(e.target.value)} />
      <p>{dog ? `${dog}'s favorite number is ${time}.` : 'enter a dog name'}</p>
    </>
  );
}
// `time` is shared with a sibling, so it stays lifted in the parent.
